            if (next[D] == 0) {
                next[D] = A;
            }
        }

        boolean[] visited = new boolean[M + 1];
        int current = C;
        int swaps = 0;

        while (true) {
            int nxt = next[current];

            if (nxt == 0) {
                System.out.println(swaps);
                return;
            }

            if (visited[current]) {
                System.out.println(-1);
                return;
            }

            visited[current] = true;
            current = nxt;
            swaps++;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }

            return val * sign;
        }
    }
}
